@Component({
  selector: 'app-login',
  templateUrl: './login.component.html'
})
export class LoginComponent {
  name: string = ''; // ← ИНИЦИАЛИЗИРУЙТЕ КАК СТРОКУ
  password: string = ''; // ← ИНИЦИАЛИЗИРУЙТЕ КАК СТРОКУ

  onSubmit() {
    console.log('Логин:', this.name);
    console.log('Пароль:', this.password);
    // Здесь будет логика входа через Keycloak
  }
}
